// Lista de nichos rotativos de alto valor na Baixada Santista
const niches = [
  { query: 'Clínica Odontológica em Santos SP', segment: 'Odontologia', city: 'Santos' },
  { query: 'Oficina Mecânica em Santos SP', segment: 'Oficina Mecânica', city: 'Santos' },
  { query: 'Restaurante e Hamburgueria em Praia Grande SP', segment: 'Gastronomia', city: 'Praia Grande' },
  { query: 'Clínica de Estética em Santos SP', segment: 'Estética', city: 'Santos' },
  { query: 'Pet Shop e Veterinária em São Vicente SP', segment: 'Pet Care', city: 'São Vicente' }
];

// Seleciona um nicho com base na semana do ano para rodízio automático
const weekNumber = Math.floor((new Date().getTime() / (1000 * 60 * 60 * 24 * 7)) % niches.length);
const selected = niches[weekNumber];

return [{
  json: {
    searchQuery: selected.query,
    segment: selected.segment,
    city: selected.city,
    maxCrawledPlacesPerSearch: 10
  }
}];

const items = $input.all().map(item => item.json);
const segmentDefault = $('Definir Nicho & Parâmetros').item.json.segment || 'Geral';
const cityDefault = $('Definir Nicho & Parâmetros').item.json.city || 'Santos';

const validLeads = [];

for (const place of items) {
  const name = place.title || place.name;
  const phone = place.phoneUnformatted || place.phone || '';
  const website = place.website || '';
  const category = place.categoryName || segmentDefault;
  const city = place.city || cityDefault;

  // Prioriza estabelecimentos com contato para abordagem comercial
  if (name && (phone || website)) {
    validLeads.push({
      json: {
        empresa: name,
        segmento: category,
        cidade: city,
        uf: 'SP',
        telefone: phone,
        website: website,
        mapsUrl: place.url || '',
        origem: 'Apify Google Maps (n8n)'
      }
    });
  }
}

return validLeads;

